// HasOwner applies the HasEdge predicate on the "owner" edge.
func HasOwner() predicate.SSHHost {
	return predicate.SSHHost(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, OwnerTable, OwnerColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOwnerWith applies the HasEdge predicate on the "owner" edge with a given conditions (other predicates).
func HasOwnerWith(preds ...predicate.User) predicate.SSHHost {
	return predicate.SSHHost(func(s *sql.Selector) {
		step := newOwnerStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasSharedUsers applies the HasEdge predicate on the "shared_users" edge.
func HasSharedUsers() predicate.SSHHost {
	return predicate.SSHHost(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2M, false, SharedUsersTable, SharedUsersPrimaryKey...),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSharedUsersWith applies the HasEdge predicate on the "shared_users" edge with a given conditions (other predicates).
func HasSharedUsersWith(preds ...predicate.User) predicate.SSHHost {
	return predicate.SSHHost(func(s *sql.Selector) {
		step := newSharedUsersStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.SSHHost) predicate.SSHHost {
	return predicate.SSHHost(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.SSHHost) predicate.SSHHost {
	return predicate.SSHHost(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.SSHHost) predicate.SSHHost {
	return predicate.SSHHost(sql.NotPredicates(p))
}
